import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Help Centre","description":"","frontmatter":{},"headers":[],"relativePath":"help/index.md","filePath":"help/index.md"}'),n={name:"help/index.md"};function o(s,e,l,h,c,d){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="help-centre" tabindex="-1">Help Centre <a class="header-anchor" href="#help-centre" aria-label="Permalink to &quot;Help Centre&quot;">​</a></h1><h2 id="customer-reference" tabindex="-1">Customer reference <a class="header-anchor" href="#customer-reference" aria-label="Permalink to &quot;Customer reference&quot;">​</a></h2><ul><li><a href="/help/faq.html">Frequently asked questions</a></li><li><a href="/help/glossary.html">Terminology glossary</a></li><li><a href="/help/feature-availability.html">Feature availability matrix</a></li></ul><h2 id="i-cannot-create-a-reservation" tabindex="-1">I cannot create a reservation <a class="header-anchor" href="#i-cannot-create-a-reservation" aria-label="Permalink to &quot;I cannot create a reservation&quot;">​</a></h2><p>Check your role, active operating hub, vehicle class, route and verified quotation. See <a href="/plus/create-reservation.html">Create a reservation</a>.</p><h2 id="the-customer-has-no-email-address" tabindex="-1">The customer has no email address <a class="header-anchor" href="#the-customer-has-no-email-address" aria-label="Permalink to &quot;The customer has no email address&quot;">​</a></h2><p>In TransferBook+ email is optional. Enter the real contact telephone number and leave email empty. See <a href="/plus/passenger-information.html">Passenger information</a>.</p><h2 id="the-price-is-missing-or-requires-a-quotation" tabindex="-1">The price is missing or requires a quotation <a class="header-anchor" href="#the-price-is-missing-or-requires-a-quotation" aria-label="Permalink to &quot;The price is missing or requires a quotation&quot;">​</a></h2><p>An unconfigured route is not a free service. Follow the <a href="/plus/manual-quotations.html">manual quotation workflow</a>.</p><h2 id="i-cannot-dispatch-a-booking" tabindex="-1">I cannot dispatch a booking <a class="header-anchor" href="#i-cannot-dispatch-a-booking" aria-label="Permalink to &quot;I cannot dispatch a booking&quot;">​</a></h2><p>Check status, pending quotation, assignment permissions, driver availability and capacity. See <a href="/plus/dispatch-schedule.html">Dispatch schedule</a>.</p><h2 id="an-integration-is-unavailable" tabindex="-1">An integration is unavailable <a class="header-anchor" href="#an-integration-is-unavailable" aria-label="Permalink to &quot;An integration is unavailable&quot;">​</a></h2><p>Check whether the service is configured and approved. Do not bypass disabled controls. See <a href="/integrations/">Integrations</a>.</p><h2 id="detailed-troubleshooting" tabindex="-1">Detailed troubleshooting <a class="header-anchor" href="#detailed-troubleshooting" aria-label="Permalink to &quot;Detailed troubleshooting&quot;">​</a></h2><ul><li><a href="/help/booking-problems.html">Booking form and submission problems</a></li><li><a href="/help/pricing-problems.html">Missing tariffs and price differences</a></li><li><a href="/help/dispatch-problems.html">Dispatch conflicts and missing assignments</a></li><li><a href="/help/access-and-session.html">Access, permissions and session errors</a></li><li><a href="/help/website-draft-problems.html">Missing drafts and package errors</a></li><li><a href="/help/integration-problems.html">Unavailable integrations and payment uncertainty</a></li></ul>',15)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
